Blockly.Msg.MICROBIT_SPI_INIT = "Initialise SPI communication with parameters <b>baudrate</b>, <b>bits</b>, <b>mode</b>, <b>sclk</b>, <b>mosi</b> and <b>miso</b>. <b>baudrate</b> defines the communication speed. <b>bits</b> defines the size of transmitted bytes (currently only <b>bits=8</b> is supported). <b>mode</b> determines the clock polarity and phase. <b>sclk</b>, <b>mosi</b> and <b>miso</b> specify the pins used.";
Blockly.Msg.MICROBIT_SPI_READ = "Reads up to <b>nbytes</b> while continuously writing the single byte given by <b>out</b>. Returns what was read (bytes).";
Blockly.Msg.MICROBIT_SPI_WRITE = "Writes the <b>buffer</b> of bytes to the SPI bus.";
Blockly.Msg.MICROBIT_SPI_WRITE_READINTO = "Writes the <b>out</b> buffer to the bus and reads any response into the <b>in</b> buffer. The buffers must have the same length and can be the same object.";
