ACMsg.MICROBIT_RESET = "Restablece la placa micro:bit por programación, equivalente a pulsar el botón de reinicio.";
ACMsg.MICROBIT_SLEEP = "Pausa el programa durante <b>ms</b> milisegundos.";
ACMsg.MICROBIT_RUNNING_TIME = "Devuelve el tiempo transcurrido desde que arrancó la placa, en milisegundos.";
ACMsg.MICROBIT_PANIC = "Muestra el error <b>error_code</b> en la matriz LED y reinicia la placa.";
ACMsg.MICROBIT_TEMPERATURE = "Devuelve la temperatura aproximada de la placa en grados Celsius.";
ACMsg.MICROBIT_SET_VOLUME = "Ajusta el volumen global de sonido al valor <b>volume</b> entre 0 y 255.";
ACMsg.MICROBIT_WS2812_WRITE = "Escribe el contenido del búfer <b>buf</b> en una tira LED WS2812 conectada a <b>pin</b>. El búfer debe ser bytes o bytearray.";
ACMsg.MICROBIT_RUN_EVERY = "Programa la ejecución de una función en el intervalo especificado por los argumentos de tiempo. Cada argumento corresponde a una unidad de tiempo diferente y se suman. Así, <b>run_every(min=1, s=30)</b> programa la ejecución cada minuto y medio. Cuando se lanza una excepción dentro de la función, la función se desprograma. Para evitarlo puedes capturar las excepciones con <b>try/except</b>. <b>run_every</b> también puede usarse como decorador, colocándolo encima de la función a programar.";
ACMsg.MICROBIT_SCALE = "Convierte <b>value</b> desde el intervalo definido por <b>from_low</b> y <b>from_high</b> a un nuevo intervalo definido por <b>to_low</b> y <b>to_high</b>.";
ACMsg.MICROBIT_RUN_EVERY_DECORATOR = "Programa la ejecución de una función en el intervalo especificado por los argumentos de tiempo. Cada argumento corresponde a una unidad de tiempo diferente y se suman. Así, <b>run_every(min=1, s=30)</b> programa la ejecución cada minuto y medio. Cuando se produce una excepción en la función programada, esta se detiene. Para evitarlo, puedes manejar las excepciones con <b>try/except</b>. <b>run_every</b> también puede usarse como función, pasando la función a programar como primer argumento.";
ACMsg.MICROBIT_DISPLAY = "Este módulo controla la pantalla LED 5x5 del frontal de la placa. Se puede usar para mostrar imágenes, animaciones e incluso texto.";
ACMsg.MICROBIT_DISPLAY_GET_PIXEL = "Devuelve el brillo del LED en la columna <b>x</b> y fila <b>y</b> como un entero entre <b>0</b> (apagado) y <b>9</b> (brillo máximo).";
ACMsg.MICROBIT_DISPLAY_SET_PIXEL = "Establece el brillo del LED en la columna <b>x</b> y fila <b>y</b> a <b>value</b>, que debe ser un entero entre <b>0</b> y <b>9</b>.";
ACMsg.MICROBIT_DISPLAY_CLEAR = "Establece el brillo de todos los LEDs a <b>0</b> (apagado).";
ACMsg.MICROBIT_DISPLAY_SHOW = "Muestra la <b>image</b>.";
ACMsg.MICROBIT_DISPLAY_SHOW_ADVANCED = "Si <b>image</b> es una cadena, float o integer, muestra letras/dígitos en secuencia. Si no, si <b>image</b> es una secuencia iterable de imágenes, muestra esas imágenes en secuencia. Cada letra, dígito o imagen se muestra con <b>delay</b> milisegundos entre ellos. Si <b>wait</b> es <b>True</b>, esta función bloqueará hasta que termine la animación; de lo contrario la animación se ejecutará en segundo plano. Si <b>loop</b> es <b>True</b>, la animación se repetirá indefinidamente. Si <b>clear</b> es <b>True</b>, la pantalla se limpiará al acabar el iterable. Ten en cuenta que los argumentos <b>wait</b>, <b>loop</b> y <b>clear</b> deben especificarse mediante su nombre.";
ACMsg.MICROBIT_DISPLAY_SCROLL = "Desplaza horizontalmente en la pantalla el <b>text</b>. Si <b>text</b> es integer o float primero se convierte a cadena con <b>str()</b>. El parámetro <b>delay</b> controla la velocidad del desplazamiento. Si <b>wait</b> es <b>True</b>, esta función bloqueará hasta que termine la animación; de lo contrario la animación se ejecutará en segundo plano. Si <b>loop</b> es <b>True</b>, la animación se repetirá indefinidamente. Si <b>monospace</b> es <b>True</b>, los caracteres ocuparán <b>5</b> columnas de píxeles de ancho cada uno; de lo contrario habrá exactamente <b>1</b> columna de píxeles en blanco entre cada carácter mientras se desplazan. Ten en cuenta que los argumentos <b>wait</b>, <b>loop</b> y <b>monospace</b> deben especificarse usando sus nombres.";
ACMsg.MICROBIT_DISPLAY_ON = "Usa <b>on()</b> para encender la pantalla.";
ACMsg.MICROBIT_DISPLAY_OFF = "Usa <b>off()</b> para apagar la pantalla (permitiendo reutilizar los pines GPIO asociados a la pantalla para otros usos).";
ACMsg.MICROBIT_DISPLAY_IS_ON = "Devuelve <b>True</b> si la pantalla está encendida, de lo contrario devuelve <b>False</b>.";
ACMsg.MICROBIT_DISPLAY_READ_LIGHT_LEVEL = "Usa los LEDs de la pantalla en modo polarización inversa para detectar la cantidad de luz que incide en la pantalla. Devuelve un entero entre <b>0</b> y <b>255</b> que representa el nivel de luz, donde un valor mayor indica más luz.";
ACMsg.MICROBIT_IMAGE = "La clase <b>Image</b> se usa para crear imágenes que pueden mostrarse fácilmente en la matriz LED del dispositivo. Con un objeto imagen es posible mostrarlo mediante la API <b>display</b>."
ACMsg.MICROBIT_IMAGE_CONSTRUCTOR_STR = "Si se usa <b>string</b>, la cadena debe constar de dígitos del 0 al 9 organizados en filas que describen la imagen, por ejemplo: <pre>\n\nimage = Image('09090:'\n\t '99999:'\n\t '99999:'\n\t '09990:'\n\t '00900:')\n</pre> creará una imagen 5x5 con forma de X. El final de una fila se indica con dos puntos.";
ACMsg.MICROBIT_IMAGE_CONSTRUCTOR_BUF = "Este método crea una imagen vacía con <b>width</b> columnas y <b>height</b> filas. El parámetro <b>buffer</b> puede ser un array de tamaño <b>width</b> * <b>height</b> que contenga enteros de 0 a 0. Por ejemplo: <pre>\n\nImage(2, 2, b'\\x08\\x08\\x08\\x08')\nou\nImage(2, 2, bytearray([9,9,9,9]))\n\n</pre>crea una imagen 2x2 con brillo 9.";
ACMsg.MICROBIT_IMAGE_BUILTIN_SEQ = "Secuencia integrada de imágenes (animación), por ejemplo <b>Image.ALL_CLOCKS</b> o <b>Image.ALL_ARROWS</b>.";
ACMsg.MICROBIT_IMAGE_HEIGHT = "Devuelve la altura de la imagen (número de filas).";
ACMsg.MICROBIT_IMAGE_WIDTH = "Devuelve el ancho de la imagen (número de columnas).";
ACMsg.MICROBIT_IMAGE_COPY = "Devuelve una copia de la imagen.";
ACMsg.MICROBIT_IMAGE_INVERT = "Devuelve una nueva imagen con el brillo de los píxeles invertido.";
ACMsg.MICROBIT_IMAGE_GET_PIXEL = "Devuelve el brillo en la columna <b>x</b> y fila <b>y</b> como un entero de <b>0</b> a <b>9</b>.";
ACMsg.MICROBIT_IMAGE_SET_PIXEL = "Establece el brillo en la columna <b>x</b> y fila <b>y</b> a <b>value</b> (un entero de <b>0</b> a <b>9</b>).";
ACMsg.MICROBIT_IMAGE_FILL = "Establece todos los píxeles a <b>value</b> (un entero de <b>0</b> a <b>9</b>).";
ACMsg.MICROBIT_IMAGE_SHIFT_LEFT = "Devuelve una nueva imagen desplazada hacia la izquierda <b>n</b> columnas.";
ACMsg.MICROBIT_IMAGE_SHIFT_RIGHT = "Devuelve una nueva imagen desplazada hacia la derecha <b>n</b> columnas.";
ACMsg.MICROBIT_IMAGE_SHIFT_UP = "Devuelve una nueva imagen desplazada hacia arriba <b>n</b> filas.";
ACMsg.MICROBIT_IMAGE_SHIFT_DOWN = "Devuelve una nueva imagen desplazada hacia abajo <b>n</b> filas.";
ACMsg.MICROBIT_IMAGE_CROP = "Devuelve una nueva imagen recortada del rectángulo que comienza en <b>x</b>, <b>y</b> con tamaño <b>w</b> x <b>h</b>.";
